import Foundation
import CryptoKit

enum ReviewedAnswerTests {
    static let fixtureData = Data(base64Encoded: "")!
    static func run(_ check: (String, Bool) -> Void) {
        do {
            let data = Data(base64Encoded: "")!
            let catalog = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: authenticated synthetic fixture decodes", catalog.answers.count == 1)
            let source = catalog.sources[0]
            let doc = KBDocument(name: source.name, chunkCount: 1, addedAt: .now, contentSHA256: source.sha256)
            let active = catalog.admitted(documents: [doc], folders: [], profileID: nil)
            check("reviewed: exact imported source admits a whole reply", active.answers.count == 1)
            check("reviewed: original byte-exact evidence stays local", active.references(for: active.answers[0].id).first?.text == catalog.answers[0].evidence[0].quote)
            check("reviewed: unknown evidence ID cannot create a quote", active.references(for: "not-admitted").isEmpty)
            check("reviewed: lexical retrieval narrows to an admitted ID", active.candidates(question: "export saved draft", referenceNames: []).first?.id == catalog.answers[0].id)
            check("reviewed: a different explicit version cannot select a product reply", active.candidates(question: "export saved draft in version 1.2.4", referenceNames: []).isEmpty)
            check("reviewed: the documented explicit version remains eligible", active.permitsVersion(for: catalog.answers[0].id, question: "export with 1.2.3"))
            let legacy = KBDocument(name: source.name, chunkCount: 1, addedAt: .now)
            check("reviewed: legacy unknown fingerprint is not admitted", catalog.admitted(documents: [legacy], folders: [], profileID: nil).answers.isEmpty)
            let changed = KBDocument(name: source.name, chunkCount: 1, addedAt: .now, contentSHA256: String(repeating: "f", count: 64))
            check("reviewed: replaced source is not admitted", catalog.admitted(documents: [changed], folders: [], profileID: nil).answers.isEmpty)
            var off = doc; off.scope = .off
            let disabled = catalog.admitted(documents: [off], folders: [], profileID: nil)
            check("reviewed: disabled source is not admitted", disabled.answers.isEmpty)
            check("reviewed: source change invalidates an in-flight revision", disabled.revisionToken != active.revisionToken)
            check("reviewed: duplicate user-document names fail closed", catalog.admitted(documents: [doc,doc], folders: [], profileID: nil).answers.isEmpty)
            var privateDoc = doc; privateDoc.scope = .only([UUID()])
            check("reviewed: other profile cannot use the source", catalog.admitted(documents: [privateDoc], folders: [], profileID: UUID()).answers.isEmpty)
            var envelope = try JSONSerialization.jsonObject(with: data) as! [String: Any]
            let payload = Data(base64Encoded: envelope["payload"] as! String)!
            let originalSignature = envelope["signature"] as! String
            let raw = try JSONDecoder().decode(ReviewedAnswerCatalog.self, from: payload)
            check("reviewed: direct raw JSON decode cannot admit itself", raw.admitted(documents: [doc], folders: [], profileID: nil).answers.isEmpty)
            do { _ = try ReviewedAnswerCatalog.decode(payload); check("reviewed: unsigned file rejected", false) } catch { check("reviewed: unsigned file rejected", true) }
            var bad = Data(base64Encoded: envelope["signature"] as! String)!; bad[0] ^= 1
            envelope["signature"] = bad.base64EncodedString()
            do { _ = try ReviewedAnswerCatalog.decode(JSONSerialization.data(withJSONObject: envelope)); check("reviewed: changed signature rejected", false) } catch { check("reviewed: changed signature rejected", true) }
            envelope["signature"] = try Curve25519.Signing.PrivateKey().signature(for: payload).base64EncodedString()
            do { _ = try ReviewedAnswerCatalog.decode(JSONSerialization.data(withJSONObject: envelope)); check("reviewed: foreign signer rejected", false) } catch { check("reviewed: foreign signer rejected", true) }
            envelope["signature"] = originalSignature
            var changedPayload = payload; changedPayload.append(0x20)
            envelope["payload"] = changedPayload.base64EncodedString()
            do { _ = try ReviewedAnswerCatalog.decode(JSONSerialization.data(withJSONObject: envelope)); check("reviewed: exact signed payload binding", false) } catch { check("reviewed: exact signed payload binding", error.localizedDescription.contains("trusted catalog signature")) }
        } catch { check("reviewed: valid fixture error " + error.localizedDescription, false) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "missing-version", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "missing-version", error.localizedDescription.contains("reply omits its product-version scope")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "unknown-client-state", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "unknown-client-state", error.localizedDescription.contains("requires unverified client state")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "overlength", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "overlength", error.localizedDescription.contains("not a complete short unit")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "three-sentences", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "three-sentences", error.localizedDescription.contains("not a complete short unit")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "unreviewed", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "unreviewed", error.localizedDescription.contains("no matching source-review receipt")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "quote-mismatch", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "quote-mismatch", error.localizedDescription.contains("evidence is not exact source text")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "bad-range", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "bad-range", error.localizedDescription.contains("invalid evidence range")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "unknown-source", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "unknown-source", error.localizedDescription.contains("unknown evidence source")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "source-hash", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "source-hash", error.localizedDescription.contains("source text hash mismatch")) }
        do {
            let data = Data(base64Encoded: "")!
            _ = try ReviewedAnswerCatalog.decode(data)
            check("reviewed: signed invalid fixture rejected " + "source-revision", false)
        } catch { check("reviewed: signed invalid fixture rejected " + "source-revision", error.localizedDescription.contains("source identity changed")) }
    }
}
